export PATH="$HOME/.bun/bin:$PATH"; bun -e '
const m = await import("/mnt/dados/opencode/config/plugins/circuit-breaker.ts");
const h = await m.CircuitBreaker();
const mk = (id) => ({ tool: "bash", sessionID: "s1", callID: id });
const cmd = () => ({ args: { command: `ls "/mnt/dados/cerebro con IA/"` } });
// tentativa 1
await h["tool.execute.before"](mk("c1"), cmd());
await h["tool.execute.after"](mk("c1"), { output: "No such file or directory", metadata: { exit: 2 } });
// tentativa 2
await h["tool.execute.before"](mk("c2"), cmd());
await h["tool.execute.after"](mk("c2"), { output: "No such file or directory", metadata: { exit: 2 } });
// tentativa 3: DEVE BLOQUEAR
try {
  await h["tool.execute.before"](mk("c3"), cmd());
  console.log("FALHOU: nao bloqueou na 3a");
} catch (e) {
  console.log("OK 3a BLOQUEADA:", String(e.message).slice(0, 60));
}
// comando diferente passa
await h["tool.execute.before"](mk("c4"), { args: { command: "ls /mnt/dados" } });
console.log("OK comando variado passa");
// sucesso reseta
await h["tool.execute.before"](mk("c5"), { args: { command: "echo hi" } });
await h["tool.execute.after"](mk("c5"), { output: "hi", metadata: { exit: 0 } });
await h["tool.execute.before"](mk("c6"), { args: { command: "echo hi" } });
await h["tool.execute.after"](mk("c6"), { output: "", metadata: { exit: 0 } });
await h["tool.execute.before"](mk("c7"), { args: { command: "echo hi" } });
console.log("OK sucesso nao acumula");
'

